+// TestImportWorkspace_OrganizationIDPresentInRequestBody verifies that
+// Client.ImportWorkspace serialises OrganizationID into the JSON request body.
+// This is the defence-in-depth regression guard: if the field is ever silently
+// dropped by a struct change, this test fails at CI time.
+func TestImportWorkspace_OrganizationIDPresentInRequestBody(t *testing.T) {
+	const wantOrgID = "aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa"
+	const wantWSID = "bbbbbbbb-bbbb-bbbb-bbbb-bbbbbbbbbbbb"
+
+	var capturedBody map[string]interface{}
+
+	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
+		if r.URL.Path != "/internal/workspaces/import" {
+			t.Fatalf("unexpected path: %s", r.URL.Path)
+		}
+		raw, err := io.ReadAll(r.Body)
+		if err != nil {
+			t.Fatalf("read request body: %v", err)
+		}
+		if err := json.Unmarshal(raw, &capturedBody); err != nil {
+			t.Fatalf("decode request body: %v", err)
+		}
+		w.WriteHeader(http.StatusOK)
+		_ = json.NewEncoder(w).Encode(map[string]string{"workspace_id": wantWSID})
+	}))
+	defer srv.Close()
+
+	client := New(srv.URL)
+	_, err := client.ImportWorkspace(context.Background(), ImportRequest{
+		RepoURL:        "https://github.com/org/repo",
+		OrganizationID: wantOrgID,
+	})
+	if err != nil {
+		t.Fatalf("unexpected error: %v", err)
+	}
+
+	got, ok := capturedBody["organization_id"]
+	if !ok {
+		t.Fatal("organization_id field missing from request body sent to adapter-service")
+	}
+	if got != wantOrgID {
+		t.Errorf("organization_id = %q, want %q", got, wantOrgID)
+	}
+}
