+
+func (c *capturingAdapter) ImportWorkspace(_ context.Context, req adapter.ImportRequest) (string, error) {
+	c.captured = req
+	return c.importID, nil
+}
+func (c *capturingAdapter) SyncWorkspace(_ context.Context, _ string) error { return nil }
