+// TestImportWorkspace_SessionOrganizationIDOverridesBodyValue proves that the
+// handler discards the client-supplied organization_id and replaces it with the
+// value from the authenticated session context before forwarding to the adapter.
+// The session is always authoritative; the body value is ignored.
+func TestImportWorkspace_SessionOrganizationIDOverridesBodyValue(t *testing.T) {
+	ws := makeTestWorkspace()
+	db := &fakeDB{workspaces: []database2.Workspace{ws}}
+
+	cap := &capturingAdapter{importID: handlerTestWSID}
+
+	sessionOrg := "session-org-uuid-1111-1111-111111111111"
+	ac := &authmw.AuthCtx{
+		UserID:                 "user-1",
+		OrganizationID:         sessionOrg,
+		AccessibleWorkspaceIDs: []string{handlerTestWSID},
+	}
+	r := newAuthTestRouter(db, cap, ac)
+
+	// Body intentionally supplies a different organization_id — the handler must overwrite it.
+	body := `{"repo_url":"https://github.com/org/repo","organization_id":"client-supplied-should-be-ignored"}`
+	w := httptest.NewRecorder()
+	req, _ := http.NewRequestWithContext(context.Background(), http.MethodPost, "/api/workspaces/import", strings.NewReader(body))
+	req.Header.Set("Content-Type", "application/json")
+	r.ServeHTTP(w, req)
+
+	if w.Code != http.StatusOK {
+		t.Fatalf("expected 200, got %d: %s", w.Code, w.Body.String())
+	}
+
+	if cap.captured.OrganizationID != sessionOrg {
+		t.Errorf("adapter received OrganizationID=%q, want session value %q", cap.captured.OrganizationID, sessionOrg)
+	}
+}

